/* blob / packed families: the same program embeds a data blob in a dedicated
 * section and prints its CRC-32. build.sh compiles it twice per variant:
 *   - plainblob: the blob is plain generated text   (low entropy)
 *   - packed:    the blob is the zlib-compressed text (high entropy)
 * There is no unpacking stub: the point is a controlled entropy contrast
 * between otherwise-identical binaries. */
#include "platform.h"
#include "blob_data.h" /* generated by gen_blob.py: bs_blob[], BS_BLOB_LEN */

static unsigned int crc32(const unsigned char *p, bs_size n) {
    unsigned int c = 0xFFFFFFFFu;
    for (bs_size i = 0; i < n; i++) {
        c ^= p[i];
        for (int k = 0; k < 8; k++) c = (c >> 1) ^ (0xEDB88320u & (0u - (c & 1u)));
    }
    return ~c;
}

int main(void) {
    static const char hex[] = "0123456789abcdef";
    char line[] = "blob crc32 = 00000000";
    unsigned int c = crc32(bs_blob, BS_BLOB_LEN);
    for (int i = 0; i < 8; i++) line[20 - i] = hex[(c >> (4 * i)) & 0xF];
    bs_print(line);
    return 0;
}
